# Clean and convert SCOREMARGIN to numeric values
def clean_scoremargin(value):
    # Check if it's already NaN (float type)
    if isinstance(value, float) and pd.isna(value):
        return np.nan

    # Convert to string if not already
    value_str = str(value).strip()

    # If it's "NaN" or "TIE", return NaN
    if value_str.upper() in ['NAN', 'TIE']:
        return np.nan

    # Remove non-numeric characters except for negative sign and decimal point
    cleaned = re.sub(r'[^-\d.]', '', value_str)

    try:
        if cleaned and cleaned != '-':
            return float(cleaned)
        else:
            return np.nan
    except:
        return np.nan

# Apply the cleaning function
df['SCOREMARGIN_NUMERIC'] = df['SCOREMARGIN'].apply(clean_scoremargin)

# Check the cleaned values
print("Cleaned SCOREMARGIN values:")
print(df[['SCOREMARGIN', 'SCOREMARGIN_NUMERIC']].head(50))
print("\n\nStatistics of cleaned numeric values:")
print(df['SCOREMARGIN_NUMERIC'].describe())

